from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'english','colours','Colours',
 ('Sharing crayons','A short poem tells of children who each have a few crayons. One needs red, the other needs black. When they share, they have a full pack. In this chapter you will think about sharing, say words that begin with sounds like gr and cr, learn action words, put words in alphabetical order and make new words by joining two words.'),
 [('The poem: sharing crayons',['The poem is about children who each have some crayons, but not all the colours.','One child needs the red crayon and the other needs the black crayon.','If they share, together they have a full pack of crayons.','The poem teaches that sharing helps everyone, because together we have more than alone.']),
  ('Sounds that start words',['Some words begin with two letters that we say together, such as gr, cr, dr and pr.','Gr words include green, grey, grass, grapes and grandmother. Cr words include crayon, crab, crane, crow and cradle.','Dr words include draw, drum, dress, drop and dragon. Pr words include prince, princess, prize, pray and present.','Say each word slowly and listen to how it starts.']),
  ('Action words',['Words that tell what someone does are called action words. Examples are laugh, dance, eat, cry, swim, sleep, play, dig, jump, run, write, smile and push.','Words like carrot, leg, book and cat are not action words, because they name things.','To find an action word, ask: can someone do it? You can jump and you can write, so these are action words.']),
  ('The alphabet and alphabetical order',['There are 26 letters in the English alphabet, from A to Z.','Putting words in alphabetical order means arranging them by their first letters, in the order of the alphabet.','Apple, banana, cherry, grapes and orange are in alphabetical order because A comes before B, B before C, C before G and G before O.','If two words begin with the same letter, we look at the second letter.']),
  ('Words have friends',['Two small words can join to make one new word. Such a word is called a compound word.','Rain and bow make rainbow. News and paper make newspaper. Basket and ball make basketball. Earth and worm make earthworm. Blue and berry make blueberry.'])],
 [('Put these in alphabetical order: yellow, blue, purple, green, red.',[('Look at the first letters: Y, B, P, G, R.','We compare the first letters.'),('In the alphabet the order is B, G, P, R, Y.','Blue comes first, then green, purple, red, yellow.'),('So the order is blue, green, purple, red, yellow.','This is alphabetical order.')]),
  ('Which of these are action words: laugh, book, swim, leg?',[('Ask whether someone can do it.','A person can laugh and swim.'),('Book and leg name things.','They are not action words.'),('The action words are laugh and swim.','They tell what we do.')])],
 ('Explain what an action word is and give three examples.',['Action words tell what someone does','Run, jump, eat','Ask: can I do it?'],['Action words name things','A noun is an action word']),
 ['Sharing helps everyone to have more.','Gr, cr, dr and pr start many words.','Action words tell what someone does.','Alphabetical order follows the order of the 26 letters.','Two small words can join to make a new word.'],
 [M('1',1,'How many letters are in the English alphabet?','26',[('24','Count again: it is 26'),('20','Count again: it is 26')],'The English alphabet has 26 letters.'),
  M('2',1,'Which is an action word?','Dance',[('Carrot','Carrot names a thing'),('Book','Book names a thing')],'We can dance.'),
  M('3',1,'Which word begins with cr?','Crayon',[('Green','Green begins with gr'),('Drum','Drum begins with dr')],'Crayon begins with cr.'),
  M('4',1,'What do the children in the poem need to have a full pack?','To share their crayons',[('To buy new crayons','They share instead'),('To stop drawing','Not the idea')],'Sharing gives them a full pack.'),
  M('5',2,'Which word comes first in alphabetical order?','Apple',[('Cherry','C comes after A'),('Banana','B comes after A')],'A comes before B and C.'),
  M('6',2,'Rain + bow makes which word?','Rainbow',[('Raincoat','That uses coat'),('Bowrain','Not a word')],'Rain and bow make rainbow.'),
  F('7',2,'Leg is an action word.',False,'Leg names a body part, it is not an action.'),
  M('8',2,'Which group is in alphabetical order?','Blue, green, red',[('Red, blue, green','R comes after B and G'),('Green, blue, red','B comes before G')],'B, G, R follows the alphabet.'),
  F('9',2,'Earth + worm makes earthworm.',True,'Two words join to make one.'),
  S('10',2,'What do we call words that tell what someone does?',['action words','action word','verbs'],'They are action words.'),
  M('11',3,'Which word begins with dr?','Dragon',[('Grapes','Starts with gr'),('Princess','Starts with pr')],'Dragon begins with dr.'),
  M('12',3,'Which two words make newspaper?','News and paper',[('Net and paper','Not the right words'),('New and paper','The word is news')],'News + paper = newspaper.')],
 keep=['alphabet','action words'])
